export interface CanonicalAttributeGroup {
  code: string;
  name: string;
  description: string;
  sortOrder: number;
}

export interface CanonicalUnit {
  code: string;
  name: string;
  symbol: string;
  isBase: boolean;
  factorToBase: string;
  offsetToBase: string;
  sortOrder: number;
}

export interface CanonicalUnitDimension {
  code: string;
  name: string;
  description: string;
  units: CanonicalUnit[];
}

export interface CanonicalOptionValue {
  code: string;
  label: string;
  sortOrder: number;
}

export interface CanonicalOptionSet {
  code: string;
  name: string;
  description: string;
  values: CanonicalOptionValue[];
}

export interface CanonicalAttributeAlias {
  alias: string;
  locale: string;
}

export interface CanonicalAttributeDefinition {
  code: string;
  name: string;
  groupCode: string;
  dataType: string;
  scope: string;
  valueSource: string;
  optionSetCode: string | null;
  unitDimensionCode: string | null;
  defaultUnitCode: string | null;
  legacyUnit: string | null;
  description: string;
  exampleValue: string | null;
  validationRule: Record<string, unknown> | null;
  repeatable: boolean;
  translatable: boolean;
  aliases: CanonicalAttributeAlias[];
}

export interface CanonicalAttributeAllowedValue {
  attributeCode: string;
  code: string;
  label: string;
  sortOrder: number;
}

type AttributeOptions = Partial<
  Pick<
    CanonicalAttributeDefinition,
    | 'scope'
    | 'valueSource'
    | 'optionSetCode'
    | 'unitDimensionCode'
    | 'defaultUnitCode'
    | 'legacyUnit'
    | 'exampleValue'
    | 'validationRule'
    | 'repeatable'
    | 'translatable'
  >
> & {
  aliases?: string[];
};

function attribute(
  code: string,
  name: string,
  groupCode: string,
  dataType: string,
  description: string,
  options: AttributeOptions = {},
): CanonicalAttributeDefinition {
  const optionSetCode = options.optionSetCode ?? null;
  return {
    code: code.startsWith('ATTR_') ? code : `ATTR_${code}`,
    name,
    groupCode,
    dataType,
    scope: options.scope ?? 'PRODUCT',
    valueSource:
      options.valueSource ?? (optionSetCode ? 'STATIC' : 'NONE'),
    optionSetCode,
    unitDimensionCode: options.unitDimensionCode ?? null,
    defaultUnitCode: options.defaultUnitCode ?? null,
    legacyUnit: options.legacyUnit ?? null,
    description,
    exampleValue: options.exampleValue ?? null,
    validationRule: options.validationRule ?? null,
    repeatable: options.repeatable ?? false,
    translatable: options.translatable ?? false,
    aliases: (options.aliases ?? []).map((alias) => ({ alias, locale: 'en' })),
  };
}

function optionValues(...labels: string[]): CanonicalOptionValue[] {
  return labels.map((label, index) => ({
    code: label
      .toUpperCase()
      .replace(/[^A-Z0-9]+/gu, '_')
      .replace(/^_+|_+$/gu, ''),
    label,
    sortOrder: index,
  }));
}

