const m = (
  code: string,
  name: string,
  group: string,
  dimension: string,
  unit: string,
  description: string,
  aliases: string[] = [],
) =>
  attribute(code, name, group, 'MEASUREMENT', description, {
    unitDimensionCode: dimension,
    defaultUnitCode: unit,
    legacyUnit: unit,
    aliases,
  });

const select = (
  code: string,
  name: string,
  group: string,
  optionSetCode: string,
  description: string,
  aliases: string[] = [],
) =>
  attribute(code, name, group, 'SELECT', description, {
    optionSetCode,
    aliases,
  });

