const optionSetByCode = new Map(
  MASTER_OPTION_SETS.map((optionSet) => [optionSet.code, optionSet]),
);

export const MASTER_ATTRIBUTE_ALLOWED_VALUES: CanonicalAttributeAllowedValue[] =
  MASTER_ATTRIBUTES.flatMap((item) => {
    if (!item.optionSetCode) return [];
    const optionSet = optionSetByCode.get(item.optionSetCode);
    if (!optionSet) return [];
    return optionSet.values.map((value) => ({
      attributeCode: item.code,
      code: value.code,
      label: value.label,
      sortOrder: value.sortOrder,
    }));
  });

export const MASTER_ATTRIBUTE_LIBRARY = {
  groups: MASTER_ATTRIBUTE_GROUPS,
  unitDimensions: MASTER_UNIT_DIMENSIONS,
  optionSets: MASTER_OPTION_SETS,
  attributes: MASTER_ATTRIBUTES,
  allowedValues: MASTER_ATTRIBUTE_ALLOWED_VALUES,
} as const;

export function validateMasterAttributeLibrary(): string[] {
  const errors: string[] = [];
  const unique = (kind: string, values: string[]) => {
    const seen = new Set<string>();
    for (const value of values) {
      if (seen.has(value)) errors.push(`Duplicate ${kind} code: ${value}`);
      seen.add(value);
    }
  };

  unique('Attribute Group', MASTER_ATTRIBUTE_GROUPS.map((item) => item.code));
  unique('Unit Dimension', MASTER_UNIT_DIMENSIONS.map((item) => item.code));
  unique(
    'Unit',
    MASTER_UNIT_DIMENSIONS.flatMap((dimension) =>
      dimension.units.map((unit) => unit.code),
    ),
  );
  unique('Option Set', MASTER_OPTION_SETS.map((item) => item.code));
  unique('Attribute', MASTER_ATTRIBUTES.map((item) => item.code));

  const groupCodes = new Set(MASTER_ATTRIBUTE_GROUPS.map((item) => item.code));
  const dimensionCodes = new Set(
    MASTER_UNIT_DIMENSIONS.map((item) => item.code),
  );
  const unitCodes = new Set(
    MASTER_UNIT_DIMENSIONS.flatMap((dimension) =>
      dimension.units.map((unit) => unit.code),
    ),
  );
  const optionSetCodes = new Set(MASTER_OPTION_SETS.map((item) => item.code));

  for (const dimension of MASTER_UNIT_DIMENSIONS) {
    const baseUnits = dimension.units.filter((unit) => unit.isBase);
    if (baseUnits.length !== 1) {
      errors.push(
        `Unit Dimension ${dimension.code} must have exactly one base unit`,
      );
    }
    for (const unit of dimension.units) {
      if (
        unit.isBase &&
        (unit.factorToBase !== '1' || unit.offsetToBase !== '0')
      ) {
        errors.push(
          `Base unit ${unit.code} must use factorToBase=1 and offsetToBase=0`,
        );
      }
    }
  }

  for (const item of MASTER_ATTRIBUTES) {
    if (!groupCodes.has(item.groupCode)) {
      errors.push(
        `Attribute ${item.code} references missing group ${item.groupCode}`,
      );
    }
    if (
      item.optionSetCode &&
      !optionSetCodes.has(item.optionSetCode)
    ) {
      errors.push(
        `Attribute ${item.code} references missing Option Set ${item.optionSetCode}`,
      );
    }
    if (
      item.unitDimensionCode &&
      !dimensionCodes.has(item.unitDimensionCode)
    ) {
      errors.push(
        `Attribute ${item.code} references missing Unit Dimension ${item.unitDimensionCode}`,
      );
    }
    if (item.defaultUnitCode && !unitCodes.has(item.defaultUnitCode)) {
      errors.push(
        `Attribute ${item.code} references missing Unit ${item.defaultUnitCode}`,
      );
    }
    if (
      (item.dataType === 'SELECT' || item.dataType === 'MULTI_SELECT') &&
      !item.optionSetCode
    ) {
      errors.push(`Selectable Attribute ${item.code} has no Option Set`);
    }
    if (
      item.dataType === 'MEASUREMENT' &&
      (!item.unitDimensionCode || !item.defaultUnitCode)
    ) {
      errors.push(
        `Measurement Attribute ${item.code} has no complete unit definition`,
      );
    }
  }

  return errors;
}
